import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import java.util.List;

// Spring Data JPA interface - no implementation needed
public interface CustomerRepository extends JpaRepository<Customer, Long> {

    // Query derived from method name
    List<Customer> findByLastName(String lastName);

    // More complex derived query
    List<Customer> findByAgeGreaterThanAndCityOrderByLastNameAsc(
        int age, String city);

    // Custom JPQL when naming gets awkward
    @Query("SELECT c FROM Customer c WHERE c.email LIKE %:domain")
    List<Customer> findByEmailDomain(String domain);

    // Native SQL when JPQL isn't enough
    @Query(value = "SELECT * FROM customers WHERE created_at > NOW() - INTERVAL '30 days'", 
           nativeQuery = true)
    List<Customer> findRecentCustomers();
}

// Usage in service - Spring generates implementation
@Service
class CustomerService {
    private final CustomerRepository repository;

    List<Customer> getYoungCustomersInCity(String city) {
        return repository.findByAgeGreaterThanAndCityOrderByLastNameAsc(18, city);
    }
}

