// Java 17 + Spring Boot: JPA for CRUD, JdbcTemplate for a report
@Service
class OrderService {
    private final OrderRepository orders;     // Spring Data JPA
    private final JdbcTemplate jdbc;          // raw SQL, same DataSource

    OrderService(OrderRepository orders, JdbcTemplate jdbc) {
        this.orders = orders;
        this.jdbc = jdbc;
    }

    Order create(Order o) { return orders.save(o); }   // JPA: easy CRUD

    // JDBC: a grouped report that is awkward in JPQL
    List<SalesRow> monthlySales() {
        return jdbc.query(
            "SELECT category, SUM(total) AS revenue FROM orders " +
            "GROUP BY category ORDER BY revenue DESC",
            (rs, i) -> new SalesRow(rs.getString("category"), rs.getBigDecimal("revenue")));
    }
}
```
