// Service code that triggers N+1 problem
public void printCustomerOrders() {
    var customers = customerRepository.findAll();  // 1 query: SELECT * FROM customers

    for (var customer : customers) {
        System.out.println(customer.getName());
        var orderCount = customer.getOrders().size();  // N queries: SELECT * FROM orders WHERE customer_id = ?
        System.out.println("Orders: " + orderCount);
    }
    // Total: 1 + N queries (N+1)
}

